def solve_diagonal(grid):
    """
    Each 2 expands as:
    - Left ray: (r+k, c-k) for k = 1, 2, 3, ...
    - Right ray: (r+k, c+k) for k = 1, 2, 3, ...

    Output is the UNION of all rays, with 2 at leftmost and rightmost points, 1s in between.
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    output = [[0] * cols for _ in range(rows + 1)]

    # Collect all ray positions
    rays = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                # Left rays
                for k in range(1, max(rows, cols)):
                    gr, gc = r + k, c - k
                    if 0 <= gr <= rows and 0 <= gc < cols:
                        rays.append((gr, gc))

                # Right rays
                for k in range(1, max(rows, cols)):
                    gr, gc = r + k, c + k
                    if 0 <= gr <= rows and 0 <= gc < cols:
                        rays.append((gr, gc))

    # Group by output row
    by_row = {}
    for r, c in rays:
        if r not in by_row:
            by_row[r] = set()
        by_row[r].add(c)

    # Fill output
    for r in range(1, rows + 1):  # Skip row 0
        if r in by_row:
            positions = by_row[r]
            if positions:
                left = min(positions)
                right = max(positions)
                output[r][left] = 2
                output[r][right] = 2
                for c in range(left + 1, right):
                    output[r][c] = 1

    return output

